INSERT INTO tours (title, slug, category, duration_days, summary, cover_image_url, cover_image_alt, hero_position, card_position, max_altitude, has_page, overview_title, overview, highlights, facts, facts_note, pack_title, pack_text, inclusions, exclusions, extras_title, extras, inclusions_note, faqs, districts, cost_title, cost_text, status, sort_order) VALUES ('The Tiger''s Nest Pilgrimage', 'tigers-nest-pilgrimage', 'cultural', 5, 'A private climb to Bhutan''s most sacred monastery, paced by a first exploration of Paro and Thimphu so the pilgrimage itself arrives as an earned, unhurried climax.', '/assets/images/image/taktshang.webp', 'The Tiger''s Nest Pilgrimage', 'center 68%', '', '', 1, 'Tour Overview', 'The Tiger''s Nest Pilgrimage is a compact, deeply immersive introduction to Bhutan — built around the cliffside hike to Paro Taktsang, the monastery where Guru Rinpoche is said to have meditated in the 8th century. Beyond the hike itself, this tour weaves in the dzongs, temples and everyday life of Paro and Thimphu, guided throughout by a private cultural guide who brings each site''s history to life.', '["Hike to the cliffside Tiger''s Nest Monastery (Taktsang)","A private blessing ceremony with a resident monk","Visit Rinpung Dzong and the National Museum of Bhutan","Explore Thimphu''s memorial chorten and weekend market","A traditional farmhouse lunch with a local family","Guided throughout by a private cultural guide"]', '[{"icon":"pin","label":"Destinations","value":"Paro, Thimphu"},{"icon":"sun","label":"Best Season","value":"March–May & September–November"},{"icon":"mountain","label":"Max Altitude","value":"3,120m — Taktsang Monastery"},{"icon":"bag","label":"Accommodation","value":"Your choice — boutique to luxury"},{"icon":"meal","label":"Meals","value":"Full board — breakfast, lunch, dinner"},{"icon":"truck","label":"Transport","value":"Private SUV or luxury travel van"}]', 'Use this as a general guide to the tour. The itinerary is further customized around the season, your interests, group size and preferred duration once you enquire.', '', '', '[]', '[]', '', '[]', '', '[]', '["Paro","Thimphu"]', 'Package Cost', 'On top of the Sustainable Development Fee of $100 per person per night (see our [Tariff page](/tariff)), there''s an additional cost covering accommodation, meals, entrance fees, your guide and a private tour vehicle. Send us an enquiry below and we''ll shape a package to your dates, budget and interests.', 'published', 1);
INSERT INTO itinerary_days (tour_id, day_number, title, description) VALUES ((SELECT id FROM tours WHERE slug = 'tigers-nest-pilgrimage'), 1, 'Arrival In Paro', 'Land into one of the world''s most dramatic mountain approaches, and settle into the valley with a visit to Rinpung Dzong and a quiet walk through Paro town before your welcome dinner.');
INSERT INTO itinerary_days (tour_id, day_number, title, description) VALUES ((SELECT id FROM tours WHERE slug = 'tigers-nest-pilgrimage'), 2, 'Paro Valley', 'A slower day among the valley''s own landmarks — the National Museum at Ta Dzong, the 7th-century Kyichu Lhakhang, and a traditional farmhouse lunch with a local family, well away from any itinerary of "sights."');
INSERT INTO itinerary_days (tour_id, day_number, title, description) VALUES ((SELECT id FROM tours WHERE slug = 'tigers-nest-pilgrimage'), 3, 'Thimphu, The Capital', 'An hour over the pass into Thimphu for the Buddha Dordenma statue, Tashichho Dzong, the memorial chorten, and — timing depending — the weekend market before returning to Paro for the night.');
INSERT INTO itinerary_days (tour_id, day_number, title, description) VALUES ((SELECT id FROM tours WHERE slug = 'tigers-nest-pilgrimage'), 4, 'The Tiger''s Nest Climb', 'An early start for the cliffside climb to Taktsang, paced to your own speed with rest stops at the cafeteria viewpoint, ending with a private blessing ceremony inside the monastery with a resident monk. This is the day the whole itinerary has been building toward.');
INSERT INTO itinerary_days (tour_id, day_number, title, description) VALUES ((SELECT id FROM tours WHERE slug = 'tigers-nest-pilgrimage'), 5, 'Departure', 'A relaxed morning before your private transfer to Paro International Airport for your onward flight.');
