INSERT INTO tours (title, slug, category, duration_days, summary, cover_image_url, cover_image_alt, hero_position, card_position, max_altitude, has_page, overview_title, overview, highlights, facts, facts_note, pack_title, pack_text, inclusions, exclusions, extras_title, extras, inclusions_note, faqs, districts, cost_title, cost_text, status, sort_order) VALUES ('Royal Capital Immersion', 'royal-capital-immersion', 'cultural', 3, '', '/assets/images/image/Thimphu Attractions header2.webp', 'Royal Capital Immersion', 'center', '', '', 0, '', '', '[]', '[]', '', '', '', '[]', '[]', '', '[]', '', '[]', '[]', 'Package Cost', '', 'published', 6);
INSERT INTO tours (title, slug, category, duration_days, summary, cover_image_url, cover_image_alt, hero_position, card_position, max_altitude, has_page, overview_title, overview, highlights, facts, facts_note, pack_title, pack_text, inclusions, exclusions, extras_title, extras, inclusions_note, faqs, districts, cost_title, cost_text, status, sort_order) VALUES ('Druk Path Trek', 'druk-path-trek', 'trekking', 6, 'A compact ridgeline trek connecting Paro and Thimphu on foot, over a chain of alpine lakes — Bhutan''s most accessible introduction to Himalayan trekking.', '/assets/images/image/Snowman Race48.webp', 'Druk Path Trek', 'center 55%', '', '4,210m', 1, 'Druk Path Trek Overview', 'The Druk Path Trek is Bhutan''s most accessible high-altitude trek — a compact route linking Paro and Thimphu on foot, over a chain of ridgelines and alpine lakes, without the long approach a trek like Jomolhari or the Snowman requires.

Over six days, the trail climbs from Paro through blue pine and rhododendron forest to the ridge at Jele Dzong, then follows a string of high pastures and lakes — Jangchulakha, Jimilang Tsho, Simkotra Tsho — with Mount Jomolhari visible on a clear day from Phume La, the trek''s highest point.

The route descends past Phajoding Monastery, one of Bhutan''s largest monastic communities, into Thimphu itself — arriving in the capital on foot rather than by road. This is a fully supported camping trek, with a dedicated crew of guides, cooks and pack animals.', '["Panoramic Himalayan views, including Mount Jomolhari, from Phume La (4,210m)","A string of high alpine lakes: Jangchulakha, Jimilang Tsho and Simkotra Tsho","The ridge-top ruins of Jele Dzong above the Paro valley","Rhododendron and blue pine forest along the trail","A descent through Phajoding Monastery into Thimphu on foot","A fully supported camp with dedicated cook and trek crew"]', '[{"icon":"pin","label":"Region","value":"Paro & Thimphu Valleys"},{"icon":"clock","label":"Duration","value":"6 Days / 5 Nights"},{"icon":"mountain","label":"Max Altitude","value":"4,210m — Phume La"},{"icon":"sun","label":"Best Season","value":"March–June & September–November"},{"icon":"difficulty","label":"Difficulty","value":"Moderate"},{"icon":"bag","label":"Accommodation","value":"Full camping with support crew"},{"icon":"meal","label":"Meals","value":"Full board, cooked by trek crew"},{"icon":"truck","label":"Transportation","value":"Private vehicle, Paro to trailhead and return from Thimphu"}]', 'Use this as a general guide to the trek. The itinerary can be adjusted for extra acclimatization days, fitness level, group size and your preferred trekking dates.', 'What To Pack For The Druk Path Trek', 'Nights above 3,700m can drop well below freezing even in peak season, so layering matters more than any single piece of gear. Pack a warm sleeping bag rated to at least -5°C, a down jacket, waterproof shell, thermal base layers, sturdy broken-in hiking boots, trekking poles, a headlamp, sun protection and a basic personal first-aid kit. Your trek crew carries tents, kitchen equipment and food, so you''ll only need a daypack for the walking day itself.', '["All meals (breakfast, lunch, dinner and evening tea)","Accommodation (twin/double sharing) — single supplement extra","All transportation within the country, including transfers","Sustainable Development Fee (SDF)","Bhutan visa fee","English-speaking local guide","Sightseeing","Bottled water"]', '["Entrance fees for museums and monuments","Drukair / Bhutan Airlines fares","Travel insurance premiums","Services provided on a personal basis","Anything not mentioned under \"Cost Includes\"","Personal expenses — laundry, drinks, tips and the like"]', 'Trek Cost Includes', '["One guide","Cook and helpers","Ponies for luggage","Tents — sleeping, mess, kitchen and toilet","3 meals a day, plus evening tea","Mattresses and all other trekking accessories"]', 'Note: For this trek, a load of 15kg per person is allowed.', '[{"question":"How hard is the Druk Path Trek?","answer":"Rated moderate. There''s no technical terrain, but daily walking (4–6 hours) at altitudes up to 4,210m makes reasonable fitness and a couple of easy days worthwhile."},{"question":"What is the best time to do the Druk Path Trek?","answer":"Best done March to June or September to November, for clear skies and — in spring — rhododendrons in bloom along the trail."},{"question":"Where do you sleep on the Druk Path Trek?","answer":"The trek is fully camping-based. A support crew pitches sleeping tents, a dining tent and a kitchen tent at each campsite, with a cook preparing all meals along the route."},{"question":"Do I need a permit for the Druk Path Trek?","answer":"Yes. A trekking permit is required, arranged on your behalf as part of the package along with your Sustainable Development Fee (SDF)."},{"question":"Can beginners do the Druk Path Trek?","answer":"Yes — it''s often recommended as a first Himalayan trek, provided you''re reasonably fit and comfortable with several consecutive days of walking at altitude."}]', '["Paro","Thimphu"]', 'Trek Cost', 'On top of the Sustainable Development Fee of $100 per person per night (see our [Tariff page](/tariff)), there''s additional cost to cover trek permits, camping equipment, crew, full board meals, hotel nights in Paro and private transport. Send us an enquiry and we''ll customize a package to your dates, group size and fitness level.', 'published', 1);
INSERT INTO itinerary_days (tour_id, day_number, title, description) VALUES ((SELECT id FROM tours WHERE slug = 'druk-path-trek'), 1, 'Arrival In Paro & Trek Briefing', 'Land at Paro''s mountain-ringed airport, settle into your hotel and meet your trek crew for a gear check and route briefing over dinner.');
INSERT INTO itinerary_days (tour_id, day_number, title, description) VALUES ((SELECT id FROM tours WHERE slug = 'druk-path-trek'), 2, 'Paro To Jele Dzong (3,480m)', 'From near Ta Dzong, climb steadily through blue pine forest to camp at the ridge-top ruins of Jele Dzong, with your first views back over the Paro valley.');
INSERT INTO itinerary_days (tour_id, day_number, title, description) VALUES ((SELECT id FROM tours WHERE slug = 'druk-path-trek'), 3, 'Jele Dzong To Jangchulakha (3,780m)', 'A ridge walk through rhododendron forest and yak pastures, with Mount Jomolhari visible on a clear day.');
INSERT INTO itinerary_days (tour_id, day_number, title, description) VALUES ((SELECT id FROM tours WHERE slug = 'druk-path-trek'), 4, 'Jangchulakha To Jimilang Tsho (3,880m)', 'Descend to camp beside Jimilang Tsho, the trek''s largest lake, known locally for its giant trout.');
INSERT INTO itinerary_days (tour_id, day_number, title, description) VALUES ((SELECT id FROM tours WHERE slug = 'druk-path-trek'), 5, 'Jimilang Tsho To Phajoding (3,750m) Via Simkotra Tsho', 'Cross the trek''s high point at Phume La (4,210m), pass a second alpine lake, then descend to camp near Phajoding Monastery above Thimphu.');
INSERT INTO itinerary_days (tour_id, day_number, title, description) VALUES ((SELECT id FROM tours WHERE slug = 'druk-path-trek'), 6, 'Phajoding To Thimphu & Departure', 'A final descent into the capital on foot, before your private transfer onward.');
